// SPDX‑License‑Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

contract KeyRegistry is Ownable {
    struct KeyMeta {
        bytes32 keyHash;    // SHA‑256 of AES‑key
        uint256 created;
        bool    revoked;
    }

    mapping(bytes32 => KeyMeta) public keys;   // keyID → meta

    event NewKey   (bytes32 indexed keyID, bytes32 keyHash);
    event RevokeKey(bytes32 indexed keyID);

    function addKey(bytes32 keyID, bytes32 keyHash) external onlyOwner {
        require(keys[keyID].created == 0, "exists");
        keys[keyID] = KeyMeta(keyHash, block.timestamp, false);
        emit NewKey(keyID, keyHash);
    }

    function revokeKey(bytes32 keyID) external onlyOwner {
        require(keys[keyID].created != 0, "not found");
        keys[keyID].revoked = true;
        emit RevokeKey(keyID);
    }
}
